# Terminal-Bench's setup.sh clones github.com/TheMikeMerrill/personal-site, resets master to d7d3e4b, checks out
# HEAD~1, commits the two patch files there without a branch ("Move to Stanford"), and checks out master again.
# There is no network here, so the same history shape is rebuilt locally: four commits on master, a detached
# "Move to Stanford" commit on master~1, then back to master. master's tip edits the same <h3> line of
# _layouts/default.html as the lost commit, so merging it conflicts there, as the original's -X theirs implies.
# Fixed dates keep the commit hashes identical across builds.
cat > /root/.gitconfig <<'EOF'
[user]
	email = test@example.com
	name = Test User
[init]
	defaultBranch = master
EOF
export GIT_AUTHOR_DATE="2025-03-03T10:00:00+0000" GIT_COMMITTER_DATE="2025-03-03T10:00:00+0000"
mkdir -p /app/personal-site && cd /app/personal-site
git init -q
mkdir -p _includes _layouts _publications css
cat > _config.yml <<'EOF'
title: Mike A. Merrill
collections:
  publications:
    output: false
EOF
cat > index.html <<'EOF'
---
layout: default
---
EOF
cat > css/style.css <<'EOF'
body { font-family: 'PT Serif', serif; }
.author { font-weight: bold; }
.venue { font-style: italic; }
EOF
cat > _includes/interests.md <<'EOF'
- Machine learning for health
- Time series and sensor data
- Language models as agents
EOF
cat > _includes/contact.md <<'EOF'
- [Google Scholar](https://scholar.google.com)
- [GitHub](https://github.com/TheMikeMerrill)
EOF
cat > _includes/about.md <<'EOF'
I am a PhD student at the University of Washington.

Previously, I was a data scientist and the second full-time employee at [HealthRhythms](https://www.healthrhythms.com).
EOF
sed 's|Postdoc @ Stanford|PhD Student @ UW|' /app/resources/patch_files/default.html > _layouts/default.html
git add -A && git commit -q -m "Initial site"
export GIT_AUTHOR_DATE="2025-03-10T10:00:00+0000" GIT_COMMITTER_DATE="2025-03-10T10:00:00+0000"
cat > _publications/2023-sensor-lm.md <<'EOF'
---
title: "Language Models Still Struggle to Zero-shot Reason about Time Series"
author: "Mike A. Merrill, Mingtian Tan, Vinayak Gupta, Tom Hartvigsen, Tim Althoff"
venue: EMNLP Findings
year: 2024
---
EOF
git add -A && git commit -q -m "Add publications"
export GIT_AUTHOR_DATE="2025-03-17T10:00:00+0000" GIT_COMMITTER_DATE="2025-03-17T10:00:00+0000"
cat > _includes/about.md <<'EOF'
I am a PhD student at the University of Washington.

Previously, I was a Student Researcher at [Google Research](https://research.google/), an ML Research Intern at [Apple Health AI](https://machinelearning.apple.com/work-with-us) and a data scientist and the second full-time employee at [HealthRhythms](https://www.healthrhythms.com).
EOF
git add -A && git commit -q -m "Update about"
export GIT_AUTHOR_DATE="2025-03-24T10:00:00+0000" GIT_COMMITTER_DATE="2025-03-24T10:00:00+0000"
sed -i 's|PhD Student @ UW|PhD Candidate @ UW|' _layouts/default.html
git add -A && git commit -q -m "Update title"
export GIT_AUTHOR_DATE="2025-04-02T10:00:00+0000" GIT_COMMITTER_DATE="2025-04-02T10:00:00+0000"
git checkout -q HEAD~1
cp /app/resources/patch_files/about.md ./_includes/about.md
cp /app/resources/patch_files/default.html ./_layouts/default.html
git add -A
git commit -q -m "Move to Stanford"
git checkout -q master 2>/dev/null
unset GIT_AUTHOR_DATE GIT_COMMITTER_DATE
